@Test
@SuppressWarnings("unchecked")
public void testPropagateExceptions() {
    try {
        // mock kafka producer
        KafkaProducer<?, ?> kafkaProducerMock = mock(KafkaProducer.class);
        // partition setup
        when(kafkaProducerMock.partitionsFor(anyString())).thenReturn(// returning a unmodifiable list to mimic KafkaProducer#partitionsFor() behaviour
        Collections.singletonList(new PartitionInfo("mock_topic", 42, null, null, null)));
        // failure when trying to send an element
        when(kafkaProducerMock.send(any(ProducerRecord.class), any(Callback.class))).thenAnswer(new Answer<Future<RecordMetadata>>() {

            @Override
            public Future<RecordMetadata> answer(InvocationOnMock invocation) throws Throwable {
                Callback callback = (Callback) invocation.getArguments()[1];
                callback.onCompletion(null, new Exception("Test error"));
                return null;
            }
        });
        // make sure the FlinkKafkaProducer instantiates our mock producer
        whenNew(KafkaProducer.class).withAnyArguments().thenReturn(kafkaProducerMock);
        // (1) producer that propagates errors
        FlinkKafkaProducer09<String> producerPropagating = new FlinkKafkaProducer09<>("mock_topic", new SimpleStringSchema(), FakeStandardProducerConfig.get(), (FlinkKafkaPartitioner<String>) null);
        OneInputStreamOperatorTestHarness<String, Object> testHarness = new OneInputStreamOperatorTestHarness<>(new StreamSink(producerPropagating));
        testHarness.open();
        try {
            testHarness.processElement(new StreamRecord<>("value"));
            testHarness.processElement(new StreamRecord<>("value"));
            fail("This should fail with an exception");
        } catch (Exception e) {
            assertNotNull(e.getCause());
            assertNotNull(e.getCause().getMessage());
            assertTrue(e.getCause().getMessage().contains("Test error"));
        }
        // (2) producer that only logs errors
        FlinkKafkaProducer09<String> producerLogging = new FlinkKafkaProducer09<>("mock_topic", new SimpleStringSchema(), FakeStandardProducerConfig.get(), (FlinkKafkaPartitioner<String>) null);
        producerLogging.setLogFailuresOnly(true);
        testHarness = new OneInputStreamOperatorTestHarness<>(new StreamSink(producerLogging));
        testHarness.open();
        testHarness.processElement(new StreamRecord<>("value"));
        testHarness.processElement(new StreamRecord<>("value"));
        testHarness.close();
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

/**
 * Test for when there are more sinks than partitions.
 * <pre>
 *   		Flink Sinks:		Kafka Partitions
 * 			1	---------------->	1
 * 			2   --------------/
 * 			3   -------------/
 * 			4	------------/
 * </pre>
 */
@Test
public void testMoreFlinkThanBrokers() {
    FlinkFixedPartitioner<String> part = new FlinkFixedPartitioner<>();
    int[] partitions = new int[] { 0 };
    part.open(0, 4);
    Assert.assertEquals(0, part.partition("abc1", null, null, null, partitions));
    part.open(1, 4);
    Assert.assertEquals(0, part.partition("abc2", null, null, null, partitions));
    part.open(2, 4);
    Assert.assertEquals(0, part.partition("abc3", null, null, null, partitions));
    // check if it is changing ;)
    Assert.assertEquals(0, part.partition("abc3", null, null, null, partitions));
    part.open(3, 4);
    Assert.assertEquals(0, part.partition("abc4", null, null, null, partitions));
}

/**
 * Tests for when there are more partitions than sinks.
 * <pre>
 * 		Flink Sinks:		Kafka Partitions
 * 			1	---------------->	1
 * 			2	---------------->	2
 * 									3
 * 									4
 * 									5
 *
 * </pre>
 */
@Test
public void testFewerPartitions() {
    FlinkFixedPartitioner<String> part = new FlinkFixedPartitioner<>();
    int[] partitions = new int[] { 0, 1, 2, 3, 4 };
    part.open(0, 2);
    Assert.assertEquals(0, part.partition("abc1", null, null, null, partitions));
    Assert.assertEquals(0, part.partition("abc1", null, null, null, partitions));
    part.open(1, 2);
    Assert.assertEquals(1, part.partition("abc1", null, null, null, partitions));
    Assert.assertEquals(1, part.partition("abc1", null, null, null, partitions));
}

/*
	 * 		Flink Sinks:		Kafka Partitions
	 * 			1	------------>--->	1
	 * 			2	-----------/----> 	2
	 * 			3	----------/
	 */
@Test
public void testMixedCase() {
    FlinkFixedPartitioner<String> part = new FlinkFixedPartitioner<>();
