    p = new Path(".\\my\\relative\\path");
    assertFalse(p.isAbsolute());
    p = new Path("my\\relative\\path");
    assertFalse(p.isAbsolute());
    p = new Path("\\\\myServer\\myDir");
    assertTrue(p.isAbsolute());
}

