    p = new Path("hdfs:///myPath/");
    assertEquals("/", p.getParent().toUri().getPath());
    p = new Path("/");
    assertNull(p.getParent());
    p = new Path("C:/my/windows/path");
    assertEquals("/C:/my/windows", p.getParent().toUri().getPath());
}

