        assertTrue(e instanceof IndexOutOfBoundsException);
    }
    try {
        segment.put(pageSize, bytes);
        fail("IndexOutOfBoundsException expected");
    } catch (Exception e) {
        assertTrue(e instanceof IndexOutOfBoundsException);
    }
    try {
        segment.put(pageSize, bytes, 6, 44);
        fail("IndexOutOfBoundsException expected");
    } catch (Exception e) {
        assertTrue(e instanceof IndexOutOfBoundsException);
    }
    try {
        segment.put(pageSize - bytes.length + 1, bytes);
        fail("IndexOutOfBoundsException expected");
    } catch (Exception e) {
