        {}, // exactly 8 fields
        { new IntValue(55), new StringValue("Hi there!"), new LongValue(457354357357135L), new IntValue(345), new IntValue(-468), new StringValue("This is the message and the message is this!"), new LongValue(0L), new IntValue(465) }, // exactly 16 fields
        { new IntValue(55), new StringValue("Hi there!"), new LongValue(457354357357135L), new IntValue(345), new IntValue(-468), new StringValue("This is the message and the message is this!"), new LongValue(0L), new IntValue(465), new IntValue(55), new StringValue("Hi there!"), new LongValue(457354357357135L), new IntValue(345), new IntValue(-468), new StringValue("This is the message and the message is this!"), new LongValue(0L), new IntValue(465) }, // exactly 8 nulls
        { null, null, null, null, null, null, null, null }, // exactly 16 nulls
        { null, null, null, null, null, null, null, null, null, null, null, null, null, null, null, null }, // arbitrary example
        { new IntValue(56), null, new IntValue(-7628761), new StringValue("A test string") }, // a very long field
        { new StringValue(createRandomString(this.rand, 15)), new StringValue(createRandomString(this.rand, 1015)), new StringValue(createRandomString(this.rand, 32)) }, // two very long fields
        { new StringValue(createRandomString(this.rand, 1265)), null, new StringValue(createRandomString(this.rand, 855)) } };
        for (Value[] value : values) {
            blackboxTestRecordWithValues(value, this.rand, this.in, this.out);
        }
        // random test with records with a small number of fields
        for (int i = 0; i < 10000; i++) {
            final Value[] fields = createRandomValues(this.rand, 0, 32);
