@Test
public void testMultipleInvocationsGetPlan() {
    try {
        ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();
        // ----------- Execution 1 ---------------
        DataSet<String> data = env.fromElements("Some", "test", "data").name("source1");
        //data.print();
        data.output(new DiscardingOutputFormat<String>()).name("print1");
        data.output(new DiscardingOutputFormat<String>()).name("output1");
        {
            Plan p = env.createProgramPlan();
            assertEquals(2, p.getDataSinks().size());
            for (GenericDataSinkBase<?> sink : p.getDataSinks()) {
                assertTrue(sink.getName().equals("print1") || sink.getName().equals("output1"));
                assertEquals("source1", sink.getInput().getName());
            }
        }
        // ----------- Execution 2 ---------------
        data.writeAsText("/some/file/path").name("textsink");
        {
            Plan p = env.createProgramPlan();
            assertEquals(1, p.getDataSinks().size());
            GenericDataSinkBase<?> sink = p.getDataSinks().iterator().next();
            assertEquals("textsink", sink.getName());
            assertEquals("source1", sink.getInput().getName());
        }
    } catch (Exception e) {
        System.err.println(e.getMessage());
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testFieldsAggregate() {
    final ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();
    DataSet<Tuple5<Integer, Long, String, Long, Integer>> tupleDs = env.fromCollection(emptyTupleData, tupleTypeInfo);
    // should work
    try {
        tupleDs.aggregate(Aggregations.SUM, 1);
    } catch (Exception e) {
        Assert.fail();
    }
    // should not work: index out of bounds
    try {
        tupleDs.aggregate(Aggregations.SUM, 10);
        Assert.fail();
    } catch (IllegalArgumentException iae) {
        // we're good here
    } catch (Exception e) {
        Assert.fail();
    }
    // should not work: not applied to tuple dataset
    DataSet<Long> longDs = env.fromCollection(emptyLongData, BasicTypeInfo.LONG_TYPE_INFO);
    try {
        longDs.aggregate(Aggregations.MIN, 1);
        Assert.fail();
    } catch (InvalidProgramException uoe) {
        // we're good here
    } catch (Exception e) {
        Assert.fail();
    }
}

@Test
public void testAggregationTypes() {
    try {
        final ExecutionEnvironment env = ExecutionEnvironment.getExecutionEnvironment();
        DataSet<Tuple5<Integer, Long, String, Long, Integer>> tupleDs = env.fromCollection(emptyTupleData, tupleTypeInfo);
        // should work: multiple aggregates
        tupleDs.aggregate(Aggregations.SUM, 0).and(Aggregations.MIN, 4);
        // should work: nested aggregates
        tupleDs.aggregate(Aggregations.MIN, 2).aggregate(Aggregations.SUM, 1);
        // should not work: average on string
        try {
            tupleDs.aggregate(Aggregations.SUM, 2);
            Assert.fail();
        } catch (UnsupportedAggregationTypeException iae) {
            // we're good here
        }
    } catch (Exception e) {
        System.err.println(e.getMessage());
        e.printStackTrace();
        Assert.fail(e.getMessage());
    }
}

