public void testCompareToEqualsHashCode() {
    Assert.assertEquals(0, objectUnderTest.compareTo(objectUnderTest));
    Assert.assertEquals(objectUnderTest, objectUnderTest);
    ScheduledFutureAdapter<?> other = getDeepCopyWithAdjustedTime(0L, objectUnderTest.getTieBreakerUid());
    Assert.assertEquals(0, objectUnderTest.compareTo(other));
    Assert.assertEquals(0, other.compareTo(objectUnderTest));
    Assert.assertEquals(objectUnderTest, other);
    Assert.assertEquals(objectUnderTest.hashCode(), other.hashCode());
    other = getDeepCopyWithAdjustedTime(0L, objectUnderTest.getTieBreakerUid() + 1L);
    Assert.assertEquals(-1, Integer.signum(objectUnderTest.compareTo(other)));
    Assert.assertEquals(+1, Integer.signum(other.compareTo(objectUnderTest)));
    Assert.assertNotEquals(objectUnderTest, other);
    other = getDeepCopyWithAdjustedTime(+1L, objectUnderTest.getTieBreakerUid());
    Assert.assertEquals(-1, Integer.signum(objectUnderTest.compareTo(other)));
    Assert.assertEquals(+1, Integer.signum(other.compareTo(objectUnderTest)));
    Assert.assertNotEquals(objectUnderTest, other);
    other = getDeepCopyWithAdjustedTime(-1L, objectUnderTest.getTieBreakerUid());
    Assert.assertEquals(+1, Integer.signum(objectUnderTest.compareTo(other)));
    Assert.assertEquals(-1, Integer.signum(other.compareTo(objectUnderTest)));
    Assert.assertNotEquals(objectUnderTest, other);
}

/**
 * Tests the deployment descriptors for local, remote, and unknown partition
 * locations (with lazy deployment allowed and all execution states for the
 * producers).
 */
@Test
public void testMixedLocalRemoteUnknownDeployment() {
    boolean allowLazyDeployment = true;
    ResourceID consumerResourceId = ResourceID.generate();
    ExecutionVertex consumer = mockExecutionVertex(ExecutionState.DEPLOYING, consumerResourceId);
    // Local and remote channel are only allowed for certain execution
    // states.
    for (ExecutionState state : ExecutionState.values()) {
        // Local partition
        ExecutionVertex localProducer = mockExecutionVertex(state, consumerResourceId);
        IntermediateResultPartition localPartition = mockPartition(localProducer);
        ResultPartitionID localPartitionId = new ResultPartitionID(localPartition.getPartitionId(), localProducer.getCurrentExecutionAttempt().getAttemptId());
        ExecutionEdge localEdge = new ExecutionEdge(localPartition, consumer, 0);
        // Remote partition
        // new resource ID
        ExecutionVertex remoteProducer = mockExecutionVertex(state, ResourceID.generate());
        IntermediateResultPartition remotePartition = mockPartition(remoteProducer);
        ResultPartitionID remotePartitionId = new ResultPartitionID(remotePartition.getPartitionId(), remoteProducer.getCurrentExecutionAttempt().getAttemptId());
        ConnectionID remoteConnectionId = new ConnectionID(remoteProducer.getCurrentAssignedResource().getTaskManagerLocation(), 0);
        ExecutionEdge remoteEdge = new ExecutionEdge(remotePartition, consumer, 1);
        // Unknown partition
        // no assigned resource
        ExecutionVertex unknownProducer = mockExecutionVertex(state, null);
        IntermediateResultPartition unknownPartition = mockPartition(unknownProducer);
        ResultPartitionID unknownPartitionId = new ResultPartitionID(unknownPartition.getPartitionId(), unknownProducer.getCurrentExecutionAttempt().getAttemptId());
        ExecutionEdge unknownEdge = new ExecutionEdge(unknownPartition, consumer, 2);
        List<InputChannelDeploymentDescriptor> desc = InputChannelDeploymentDescriptor.fromEdges(Arrays.asList(localEdge, remoteEdge, unknownEdge), allowLazyDeployment);
        assertEquals(3, desc.size());
        // These states are allowed
        if (state == ExecutionState.RUNNING || state == ExecutionState.FINISHED || state == ExecutionState.SCHEDULED || state == ExecutionState.DEPLOYING) {
            // Create local or remote channels
            assertEquals(localPartitionId, desc.get(0).getConsumedPartitionId());
            assertTrue(desc.get(0).getConsumedPartitionLocation().isLocal());
            assertNull(desc.get(0).getConsumedPartitionLocation().getConnectionId());
            assertEquals(remotePartitionId, desc.get(1).getConsumedPartitionId());
            assertTrue(desc.get(1).getConsumedPartitionLocation().isRemote());
            assertEquals(remoteConnectionId, desc.get(1).getConsumedPartitionLocation().getConnectionId());
        } else {
            // Unknown (lazy deployment allowed)
            assertEquals(localPartitionId, desc.get(0).getConsumedPartitionId());
            assertTrue(desc.get(0).getConsumedPartitionLocation().isUnknown());
            assertNull(desc.get(0).getConsumedPartitionLocation().getConnectionId());
            assertEquals(remotePartitionId, desc.get(1).getConsumedPartitionId());
            assertTrue(desc.get(1).getConsumedPartitionLocation().isUnknown());
            assertNull(desc.get(1).getConsumedPartitionLocation().getConnectionId());
        }
        assertEquals(unknownPartitionId, desc.get(2).getConsumedPartitionId());
        assertTrue(desc.get(2).getConsumedPartitionLocation().isUnknown());
        assertNull(desc.get(2).getConsumedPartitionLocation().getConnectionId());
    }
}

