    currentNumber = (BUFFER_SIZE / 4) * toSkip;
    Buffer buffer;
    while ((buffer = returnedBuffers.poll()) != null) {
        currentNumber = verifyBufferFilledWithAscendingNumbers(buffer, currentNumber);
    }
