@Test
public void testResourceReleaseAfterInterruptedConnect() throws Exception {
    // Latch to synchronize on the connect call.
    final CountDownLatch syncOnConnect = new CountDownLatch(1);
    final Tuple2<NettyServer, NettyClient> netty = createNettyServerAndClient(new NettyProtocol(null, null, true) {

        @Override
        public ChannelHandler[] getServerChannelHandlers() {
            return new ChannelHandler[0];
        }

        @Override
        public ChannelHandler[] getClientChannelHandlers() {
            return new ChannelHandler[] { new CountDownLatchOnConnectHandler(syncOnConnect) };
        }
    });
    final NettyServer server = netty.f0;
    final NettyClient client = netty.f1;
    final UncaughtTestExceptionHandler exceptionHandler = new UncaughtTestExceptionHandler();
    try {
        final PartitionRequestClientFactory factory = new PartitionRequestClientFactory(client);
        final Thread connect = new Thread(new Runnable() {

            @Override
            public void run() {
                ConnectionID serverAddress = null;
                try {
                    serverAddress = createServerConnectionID(0);
                    // This triggers a connect
                    factory.createPartitionRequestClient(serverAddress);
                } catch (Throwable t) {
                    if (serverAddress != null) {
                        factory.closeOpenChannelConnections(serverAddress);
                        Thread.getDefaultUncaughtExceptionHandler().uncaughtException(Thread.currentThread(), t);
                    } else {
                        t.printStackTrace();
                        fail("Could not create RemoteAddress for server.");
                    }
                }
            }
        });
        connect.setUncaughtExceptionHandler(exceptionHandler);
        connect.start();
        // Wait on the connect
        syncOnConnect.await();
        connect.interrupt();
        connect.join();
        // Make sure that after a failed connect all resources are cleared.
        assertEquals(0, factory.getNumberOfActiveClients());
        // Make sure that the interrupt exception is not swallowed
        assertTrue(exceptionHandler.getErrors().size() > 0);
    } finally {
        if (server != null) {
            server.shutdown();
        }
        if (client != null) {
            client.shutdown();
        }
    }
}

/**
 * Tests a fix for FLINK-1627.
 *
 * <p> FLINK-1627 discovered a race condition, which could lead to an infinite loop when a
 * receiver was cancelled during a certain time of decoding a message. The test reproduces the
 * input, which lead to the infinite loop: when the handler gets a reference to the buffer
 * provider of the receiving input channel, but the respective input channel is released (and
 * the corresponding buffer provider destroyed), the handler did not notice this.
 *
 * @see <a href="https://issues.apache.org/jira/browse/FLINK-1627">FLINK-1627</a>
 */
@Test(timeout = 60000)
@SuppressWarnings("unchecked")
public void testReleaseInputChannelDuringDecode() throws Exception {
    // Mocks an input channel in a state as it was released during a decode.
    final BufferProvider bufferProvider = mock(BufferProvider.class);
    when(bufferProvider.requestBuffer()).thenReturn(null);
    when(bufferProvider.isDestroyed()).thenReturn(true);
    when(bufferProvider.addBufferListener(any(BufferListener.class))).thenReturn(false);
    final RemoteInputChannel inputChannel = mock(RemoteInputChannel.class);
    when(inputChannel.getInputChannelId()).thenReturn(new InputChannelID());
    when(inputChannel.getBufferProvider()).thenReturn(bufferProvider);
    final BufferResponse receivedBuffer = createBufferResponse(TestBufferFactory.createBuffer(TestBufferFactory.BUFFER_SIZE), 0, inputChannel.getInputChannelId(), 2);
    final PartitionRequestClientHandler client = new PartitionRequestClientHandler();
    client.addInputChannel(inputChannel);
    client.channelRead(mock(ChannelHandlerContext.class), receivedBuffer);
}

