    final ManualClock clock = new ManualClock();
    try (SlotPoolImpl slotPool = new SlotPoolImpl(jobId, clock, TestingUtils.infiniteTime(), timeout)) {
        final BlockingQueue<AllocationID> freedSlots = new ArrayBlockingQueue<>(1);
