/**
 * Tests that heap/non-heap metrics do not rely on a static MemoryUsage instance.
 *
 * <p>We can only check this easily for the currently used heap memory, so we use it this as a proxy for testing
 * the functionality in general.
 */
@Test
public void testHeapMetrics() throws Exception {
    final InterceptingOperatorMetricGroup heapMetrics = new InterceptingOperatorMetricGroup();
    MetricUtils.instantiateHeapMemoryMetrics(heapMetrics);
    @SuppressWarnings("unchecked")
    final Gauge<Long> used = (Gauge<Long>) heapMetrics.get(MetricNames.MEMORY_USED);
    final long usedHeapInitially = used.getValue();
    // check memory usage difference multiple times since other tests may affect memory usage as well
    for (int x = 0; x < 10; x++) {
        final byte[] array = new byte[1024 * 1024 * 8];
        final long usedHeapAfterAllocation = used.getValue();
        if (usedHeapInitially != usedHeapAfterAllocation) {
            return;
        }
        Thread.sleep(50);
    }
    Assert.fail("Heap usage metric never changed it's value.");
}

@Test
public void testObtainAnyMetrics() throws InterruptedException {
    SystemResourcesCounter systemResources = new SystemResourcesCounter(Time.milliseconds(10));
    double initialCpuIdle = systemResources.getCpuIdle();
    systemResources.start();
    // wait for stats to update/calculate
    try {
        double cpuIdle;
        do {
            Thread.sleep(1);
            cpuIdle = systemResources.getCpuIdle();
        } while (initialCpuIdle == cpuIdle || Double.isNaN(cpuIdle) || cpuIdle == 0.0);
    } finally {
        systemResources.shutdown();
        systemResources.join();
    }
    double totalCpuUsage = systemResources.getCpuIrq() + systemResources.getCpuNice() + systemResources.getCpuSoftIrq() + systemResources.getCpuSys() + systemResources.getCpuUser() + systemResources.getIOWait();
    assertTrue("There should be at least one processor", systemResources.getProcessorsCount() > 0);
    assertTrue("There should be at least one network interface", systemResources.getNetworkInterfaceNames().length > 0);
    assertEquals(100.0, totalCpuUsage + systemResources.getCpuIdle(), EPSILON);
}

