@Test
public void testCallFinalizeOnMasterBeforeJobCompletes() throws Exception {
    final int parallelism = 11;
    final MiniClusterConfiguration cfg = new MiniClusterConfiguration.Builder().setNumTaskManagers(1).setNumSlotsPerTaskManager(parallelism).setConfiguration(getDefaultConfiguration()).build();
    try (final MiniCluster miniCluster = new MiniCluster(cfg)) {
        miniCluster.start();
        final JobVertex source = new JobVertex("Source");
        source.setInvokableClass(WaitingNoOpInvokable.class);
        source.setParallelism(parallelism);
        final WaitOnFinalizeJobVertex sink = new WaitOnFinalizeJobVertex("Sink", 20L);
        sink.setInvokableClass(NoOpInvokable.class);
        sink.setParallelism(parallelism);
        sink.connectNewDataSetAsInput(source, DistributionPattern.POINTWISE, ResultPartitionType.PIPELINED);
        final JobGraph jobGraph = new JobGraph("SubtaskInFinalStateRaceCondition", source, sink);
        final CompletableFuture<JobSubmissionResult> submissionFuture = miniCluster.submitJob(jobGraph);
        final CompletableFuture<JobResult> jobResultFuture = submissionFuture.thenCompose((JobSubmissionResult ignored) -> miniCluster.requestJobResult(jobGraph.getJobID()));
        jobResultFuture.get().toJobExecutionResult(getClass().getClassLoader());
        assertTrue(sink.finalizedOnMaster.get());
    }
}

/**
 * Tests that the registered classes in Kryo did not change.
 *
 * <p>Once we have proper serializer versioning this test will become obsolete.
 * But currently a change in the serializers can break savepoint backwards
 * compatibility between Flink versions.
 */
@Test
public void testDefaultKryoRegisteredClassesDidNotChange() throws Exception {
    final Kryo kryo = new KryoSerializer<>(Integer.class, new ExecutionConfig()).getKryo();
    try (BufferedReader reader = new BufferedReader(new InputStreamReader(getClass().getClassLoader().getResourceAsStream("flink_11-kryo_registrations")))) {
        String line;
        while ((line = reader.readLine()) != null) {
            String[] split = line.split(",");
            final int tag = Integer.parseInt(split[0]);
            final String registeredClass = split[1];
            Registration registration = kryo.getRegistration(tag);
            if (registration == null) {
                fail(String.format("Registration for %d = %s got lost", tag, registeredClass));
            } else if (registeredClass.equals("org.apache.avro.generic.GenericData$Array")) {
                // starting with Flink 1.4 Avro is no longer a dependency of core. Avro is
                // only available if flink-avro is present. There is a special version of
                // this test in AvroKryoSerializerRegistrationsTest that verifies correct
                // registration of Avro types if present
                assertThat(registration.getType().getName(), is("org.apache.flink.api.java.typeutils.runtime.kryo.Serializers$DummyAvroRegisteredClass"));
            } else if (!registeredClass.equals(registration.getType().getName())) {
                fail(String.format("Registration for %d = %s changed to %s", tag, registeredClass, registration.getType().getName()));
            }
        }
    }
}

@Test
public void testReturnLocalHostAddressUsingHeuristics() throws Exception {
    // instead of using a unstable localhost:port as "unreachable" to cause Test fails unstably
    // using a Absolutely unreachable outside ip:port
    InetSocketAddress unreachable = new InetSocketAddress("8.8.8.8", 0xFFFF);
    final long start = System.nanoTime();
    InetAddress add = ConnectionUtils.findConnectingAddress(unreachable, 2000, 400);
    // check that it did not take forever (max 30 seconds)
    // this check can unfortunately not be too tight, or it will be flaky on some CI infrastructure
    assertTrue(System.nanoTime() - start < 30_000_000_000L);
    // we should have found a heuristic address
    assertNotNull(add);
    // make sure that we returned the InetAddress.getLocalHost as a heuristic
    assertEquals(InetAddress.getLocalHost(), add);
}

@Test
public void testFindConnectingAddressWhenGetLocalHostThrows() throws Exception {
    PowerMockito.mockStatic(InetAddress.class);
    Mockito.when(InetAddress.getLocalHost()).thenThrow(new UnknownHostException()).thenCallRealMethod();
    final InetAddress loopbackAddress = Inet4Address.getByName("127.0.0.1");
    Thread socketServerThread;
    try (ServerSocket socket = new ServerSocket(0, 1, loopbackAddress)) {
        // Make sure that the thread will eventually die even if something else goes wrong
        socket.setSoTimeout(10_000);
        socketServerThread = new Thread(new Runnable() {

            @Override
            public void run() {
                try {
                    socket.accept();
                } catch (IOException e) {
                    // ignore
                }
            }
        });
        socketServerThread.start();
        final InetSocketAddress socketAddress = new InetSocketAddress(loopbackAddress, socket.getLocalPort());
        final InetAddress address = ConnectionUtils.findConnectingAddress(socketAddress, 2000, 400);
        // Make sure we got an address via alternative means
        assertNotNull(address);
    }
}

