                fail("Test failed with unexpected exception");
            }
        } finally {
            table.close();
        }
        checkNoTempFilesRemain(ioMan);
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    } finally {
        ioMan.shutdown();
    }
}

