/**
 * Tests that the MutableHashTable spills its partitions when creating the initial table
 * without overflow segments in the partitions. This means that the records are large.
 */
@Test
public void testSpillingWhenBuildingTableWithoutOverflow() throws Exception {
    final IOManager ioMan = new IOManagerAsync();
    try {
        final TypeSerializer<byte[]> serializer = BytePrimitiveArraySerializer.INSTANCE;
        final TypeComparator<byte[]> buildComparator = new BytePrimitiveArrayComparator(true);
        final TypeComparator<byte[]> probeComparator = new BytePrimitiveArrayComparator(true);
        @SuppressWarnings("unchecked")
        final TypePairComparator<byte[], byte[]> pairComparator = new GenericPairComparator<>(new BytePrimitiveArrayComparator(true), new BytePrimitiveArrayComparator(true));
        final int pageSize = 128;
        final int numSegments = 33;
        List<MemorySegment> memory = getMemory(numSegments, pageSize);
        MutableHashTable<byte[], byte[]> table = new MutableHashTable<byte[], byte[]>(serializer, serializer, buildComparator, probeComparator, pairComparator, memory, ioMan, 1, false);
        int numElements = 9;
        table.open(new CombiningIterator<byte[]>(new ByteArrayIterator(numElements, 128, (byte) 0), new ByteArrayIterator(numElements, 128, (byte) 1)), new CombiningIterator<byte[]>(new ByteArrayIterator(1, 128, (byte) 0), new ByteArrayIterator(1, 128, (byte) 1)));
        while (table.nextRecord()) {
            MutableObjectIterator<byte[]> iterator = table.getBuildSideIterator();
            int counter = 0;
            while (iterator.next() != null) {
                counter++;
            }
            // check that we retrieve all our elements
            Assert.assertEquals(numElements, counter);
        }
        table.close();
    } finally {
        ioMan.shutdown();
    }
}

/**
 * This has to be duplicated in InPlaceMutableHashTableTest and CompactingHashTableTest
 * because of the different constructor calls.
 */
@Test
public void testHashTableGrowthWithInsert() {
    try {
        final int numElements = 1000000;
        List<MemorySegment> memory = getMemory(10000, 32 * 1024);
        InPlaceMutableHashTable<Tuple2<Long, String>> table = new InPlaceMutableHashTable<Tuple2<Long, String>>(serializer, comparator, memory);
        table.open();
        for (long i = 0; i < numElements; i++) {
            table.insert(new Tuple2<Long, String>(i, String.valueOf(i)));
        }
        // make sure that all elements are contained via the entry iterator
        {
            BitSet bitSet = new BitSet(numElements);
            MutableObjectIterator<Tuple2<Long, String>> iter = table.getEntryIterator();
            Tuple2<Long, String> next;
            while ((next = iter.next()) != null) {
                assertNotNull(next.f0);
                assertNotNull(next.f1);
                assertEquals(next.f0.longValue(), Long.parseLong(next.f1));
                bitSet.set(next.f0.intValue());
            }
            assertEquals(numElements, bitSet.cardinality());
        }
        // make sure all entries are contained via the prober
        {
            InPlaceMutableHashTable<Tuple2<Long, String>>.HashTableProber<Long> proper = table.getProber(probeComparator, pairComparator);
            Tuple2<Long, String> reuse = new Tuple2<>();
            for (long i = 0; i < numElements; i++) {
                assertNotNull(proper.getMatchFor(i, reuse));
                assertNull(proper.getMatchFor(i + numElements, reuse));
            }
        }
        table.close();
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

