        SpillingResettableIterator<IntValue> iterator = new SpillingResettableIterator<IntValue>(this.reader, this.serializer, this.memman, this.ioman, 2, this.memOwner);
        // open the iterator
        iterator.open();
        // now test walking through the iterator
        int count = 0;
