        assertThat(firstAsyncOperationFuture.get(), is(42));
        terminationFuture.get();
        assertThat(endpoint.getNumberAsyncOperationCalls(), is(1));
        assertThat(secondAsyncOperationFuture.isDone(), is(false));
    } finally {
