@Test
public void testIncrementalCleanup() throws Exception {
    assumeTrue(incrementalCleanupSupported());
    initTest(getConfBuilder(TTL).cleanupIncrementally(5, true).build());
    final int keysToUpdate = CopyOnWriteStateTable.DEFAULT_CAPACITY >> 3;
    timeProvider.time = 0;
    // create enough keys to trigger incremental rehash
    updateKeys(0, INC_CLEANUP_ALL_KEYS, ctx().updateEmpty);
    timeProvider.time = 50;
    // update some
    updateKeys(0, keysToUpdate, ctx().updateUnexpired);
    RunnableFuture<SnapshotResult<KeyedStateHandle>> snapshotRunnableFuture = sbetc.triggerSnapshot();
    // update more concurrently with snapshotting
    updateKeys(keysToUpdate, keysToUpdate * 2, ctx().updateUnexpired);
    // expire rest
    timeProvider.time = 120;
    triggerMoreIncrementalCleanupByOtherOps();
    // check rest expired and cleanup updated
    checkExpiredKeys(keysToUpdate * 2, INC_CLEANUP_ALL_KEYS);
    KeyedStateHandle snapshot = snapshotRunnableFuture.get().getJobManagerOwnedSnapshot();
    // restore snapshot which should discard concurrent updates
    timeProvider.time = 50;
    restoreSnapshot(snapshot, StateBackendTestContext.NUMBER_OF_KEY_GROUPS);
    // check rest unexpired, also after restore which should discard concurrent updates
    checkUnexpiredKeys(keysToUpdate, INC_CLEANUP_ALL_KEYS, ctx().getUpdateEmpty);
    timeProvider.time = 120;
    // remove some
    for (int i = keysToUpdate >> 1; i < keysToUpdate + (keysToUpdate >> 2); i++) {
        sbetc.setCurrentKey(Integer.toString(i));
        ctx().ttlState.clear();
    }
    // check updated not expired
    checkUnexpiredKeys(0, keysToUpdate >> 1, ctx().getUnexpired);
    triggerMoreIncrementalCleanupByOtherOps();
    // check that concurrently updated and then restored with original values are expired
    checkExpiredKeys(keysToUpdate, keysToUpdate * 2);
    timeProvider.time = 170;
    // check rest expired and cleanup updated
    checkExpiredKeys(keysToUpdate >> 1, INC_CLEANUP_ALL_KEYS);
    // check updated expired
    checkExpiredKeys(0, keysToUpdate >> 1);
}

/**
 * Test for {@link NetworkEnvironmentConfiguration#calculateNewNetworkBufferMemory(Configuration, long)}
 * using the same (manual) test cases as in {@link NetworkEnvironmentConfigurationTest#calculateHeapSizeMB()}.
 */
@Test
public void calculateNetworkBufFromHeapSize() {
    Configuration config;
    config = getConfig(Long.valueOf(TaskManagerOptions.MANAGED_MEMORY_SIZE.defaultValue()), TaskManagerOptions.MANAGED_MEMORY_FRACTION.defaultValue(), 0.1f, 60L << 20, 1L << 30, MemoryType.HEAP);
    assertEquals((100L << 20) + 1, /* one too many due to floating point imprecision */
    NetworkEnvironmentConfiguration.calculateNewNetworkBufferMemory(config, // 900MB
    900L << 20));
    config = getConfig(Long.valueOf(TaskManagerOptions.MANAGED_MEMORY_SIZE.defaultValue()), TaskManagerOptions.MANAGED_MEMORY_FRACTION.defaultValue(), 0.2f, 60L << 20, 1L << 30, MemoryType.HEAP);
    assertEquals((200L << 20) + 3, /* slightly too many due to floating point imprecision */
    NetworkEnvironmentConfiguration.calculateNewNetworkBufferMemory(config, // 800MB
    800L << 20));
    config = getConfig(10, TaskManagerOptions.MANAGED_MEMORY_FRACTION.defaultValue(), 0.1f, 60L << 20, 1L << 30, MemoryType.OFF_HEAP);
    assertEquals((100L << 20) + 1, /* one too many due to floating point imprecision */
    NetworkEnvironmentConfiguration.calculateNewNetworkBufferMemory(config, // 890MB
    890L << 20));
    config = getConfig(0, 0.1f, 0.1f, 60L << 20, 1L << 30, MemoryType.OFF_HEAP);
    assertEquals((100L << 20) + 1, /* one too many due to floating point imprecision */
    NetworkEnvironmentConfiguration.calculateNewNetworkBufferMemory(config, // 810MB
    810L << 20));
}

/**
 * Test for {@link NetworkEnvironmentConfiguration#calculateNetworkBufferMemory(long, Configuration)} using old
 * configurations via {@link TaskManagerOptions#NETWORK_NUM_BUFFERS}.
 */
@SuppressWarnings("deprecation")
@Test
public void calculateNetworkBufOld() {
    Configuration config = new Configuration();
    config.setInteger(TaskManagerOptions.NETWORK_NUM_BUFFERS, 1);
    // note: actual network buffer memory size is independent of the totalJavaMemorySize
    assertEquals(MemorySize.parse(TaskManagerOptions.MEMORY_SEGMENT_SIZE.defaultValue()).getBytes(), NetworkEnvironmentConfiguration.calculateNetworkBufferMemory(10L << 20, config));
