@Test(timeout = 2000)
@RetryOnFailure(times = 3)
public void testRocksDbListStateAPIs() throws Exception {
    final File rocksDir = tmp.newFolder();
    // ensure the RocksDB library is loaded to a distinct location each retry
    NativeLibraryLoader.getInstance().loadLibrary(rocksDir.getAbsolutePath());
    final String key1 = "key1";
    final String key2 = "key2";
    final String value = "abcdefghijklmnopqrstuvwxyz0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ7890654321";
    final byte[] keyBytes1 = key1.getBytes(StandardCharsets.UTF_8);
    final byte[] keyBytes2 = key2.getBytes(StandardCharsets.UTF_8);
    final byte[] valueBytes = value.getBytes(StandardCharsets.UTF_8);
    // The number of values added to ListState. Can be changed for benchmarking
    final int num = 10;
    try (final Options options = new Options().setCompactionStyle(CompactionStyle.LEVEL).setLevelCompactionDynamicLevelBytes(true).setIncreaseParallelism(4).setUseFsync(false).setMaxOpenFiles(-1).setCreateIfMissing(true).setMergeOperatorName(RocksDBKeyedStateBackend.MERGE_OPERATOR_NAME);
        final WriteOptions writeOptions = new WriteOptions().setSync(false).setDisableWAL(true);
        final RocksDB rocksDB = RocksDB.open(options, rocksDir.getAbsolutePath())) {
        // ----- add() API -----
        log.info("begin add");
        final long beginInsert1 = System.nanoTime();
        for (int i = 0; i < num; i++) {
            rocksDB.merge(writeOptions, keyBytes1, valueBytes);
        }
        final long endInsert1 = System.nanoTime();
        log.info("end add - duration: {} ns", (endInsert1 - beginInsert1));
        // ----- update() API -----
        List<byte[]> list = new ArrayList<>(num);
        for (int i = 0; i < num; i++) {
            list.add(valueBytes);
        }
        byte[] premerged = merge(list);
        log.info("begin update");
        final long beginInsert2 = System.nanoTime();
        rocksDB.merge(writeOptions, keyBytes2, premerged);
        final long endInsert2 = System.nanoTime();
        log.info("end update - duration: {} ns", (endInsert2 - beginInsert2));
    }
}

@Test(timeout = 2000)
@RetryOnFailure(times = 3)
public void testRocksDbMergePerformance() throws Exception {
    final int num = 50000;
    try (RocksDB rocksDB = RocksDB.open(options, rocksDir.getAbsolutePath())) {
        // ----- insert -----
        log.info("begin insert");
        final long beginInsert = System.nanoTime();
        for (int i = 0; i < num; i++) {
            rocksDB.merge(writeOptions, keyBytes, valueBytes);
        }
        final long endInsert = System.nanoTime();
        log.info("end insert - duration: {} ms", (endInsert - beginInsert) / 1_000_000);
        // ----- read (attempt 1) -----
        final byte[] resultHolder = new byte[num * (valueBytes.length + 2)];
        final long beginGet1 = System.nanoTime();
        rocksDB.get(keyBytes, resultHolder);
        final long endGet1 = System.nanoTime();
        log.info("end get - duration: {} ms", (endGet1 - beginGet1) / 1_000_000);
        // ----- read (attempt 2) -----
        final long beginGet2 = System.nanoTime();
        rocksDB.get(keyBytes, resultHolder);
        final long endGet2 = System.nanoTime();
        log.info("end get - duration: {} ms", (endGet2 - beginGet2) / 1_000_000);
        // ----- compact -----
        log.info("compacting...");
        final long beginCompact = System.nanoTime();
        rocksDB.compactRange();
        final long endCompact = System.nanoTime();
        log.info("end compaction - duration: {} ms", (endCompact - beginCompact) / 1_000_000);
        // ----- read (attempt 3) -----
        final long beginGet3 = System.nanoTime();
        rocksDB.get(keyBytes, resultHolder);
        final long endGet3 = System.nanoTime();
        log.info("end get - duration: {} ms", (endGet3 - beginGet3) / 1_000_000);
    }
}

