            @Override
            public void run() {
                try {
                    source.run(ctx);
                } catch (Throwable t) {
                    error[0] = t;
                }
            }
        };
        runner.start();
        // wait for a bit
        Thread.sleep(1000);
        // make a checkpoint
        List<Integer> checkpointData = new ArrayList<>(numElements);
        OperatorSubtaskState handles = null;
        synchronized (ctx.getCheckpointLock()) {
            handles = testHarness.snapshot(566, System.currentTimeMillis());
            checkpointData.addAll(result);
        }
        // cancel the source
        source.cancel();
        runner.join();
        // check for errors
        if (error[0] != null) {
            System.err.println("Error in asynchronous source runner");
            error[0].printStackTrace();
            fail("Error in asynchronous source runner");
        }
        final FromElementsFunction<Integer> sourceCopy = new FromElementsFunction<>(IntSerializer.INSTANCE, data);
        StreamSource<Integer, FromElementsFunction<Integer>> srcCopy = new StreamSource<>(sourceCopy);
        AbstractStreamOperatorTestHarness<Integer> testHarnessCopy = new AbstractStreamOperatorTestHarness<>(srcCopy, 1, 1, 0);
        testHarnessCopy.setup();
        testHarnessCopy.initializeState(handles);
        testHarnessCopy.open();
        // recovery run
        SourceFunction.SourceContext<Integer> newCtx = new ListSourceContext<>(checkpointData);
        sourceCopy.run(newCtx);
        assertEquals(data, checkpointData);
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

@Test
public void testMonotonousTimestamps() {
    AssignerWithPeriodicWatermarks<String> assigner = new IngestionTimeExtractor<>();
    long maxRecordSoFar = 0L;
    long maxWatermarkSoFar = 0L;
    for (int i = 0; i < 1343; i++) {
        if (i % 7 == 1) {
            Watermark mark = assigner.getCurrentWatermark();
            assertNotNull(mark);
            // increasing watermarks
            assertTrue(mark.getTimestamp() >= maxWatermarkSoFar);
            maxWatermarkSoFar = mark.getTimestamp();
            // tight watermarks
            assertTrue(mark.getTimestamp() >= maxRecordSoFar - 1);
        } else {
            long next = assigner.extractTimestamp("a", Long.MIN_VALUE);
            // increasing timestamps
            assertTrue(next >= maxRecordSoFar);
            // timestamps are never below or at the watermark
            assertTrue(next > maxWatermarkSoFar);
            maxRecordSoFar = next;
        }
        if (i % 9 == 0) {
            try {
                Thread.sleep(1);
            } catch (InterruptedException ignored) {
            }
        }
    }
}

