    whenNew(StateSnapshotContextSynchronousImpl.class).withArguments(anyLong(), anyLong(), any(CheckpointStreamFactory.class), nullable(KeyGroupRange.class), any(CloseableRegistry.class)).thenReturn(context);
    whenNew(OperatorSnapshotFutures.class).withAnyArguments().thenReturn(operatorSnapshotResult);
