public void testStreamQueryExecutionSink() throws Exception {
    final String csvOutputPath = new File(tempFolder.newFolder().getAbsolutePath(), "test-out.csv").toURI().toString();
    final URL url = getClass().getClassLoader().getResource("test-data.csv");
    Objects.requireNonNull(url);
    final Map<String, String> replaceVars = new HashMap<>();
    replaceVars.put("$VAR_SOURCE_PATH1", url.getPath());
    replaceVars.put("$VAR_EXECUTION_TYPE", "streaming");
    replaceVars.put("$VAR_SOURCE_SINK_PATH", csvOutputPath);
    replaceVars.put("$VAR_UPDATE_MODE", "update-mode: append");
    replaceVars.put("$VAR_MAX_ROWS", "100");
    final Executor executor = createModifiedExecutor(clusterClient, replaceVars);
    final SessionContext session = new SessionContext("test-session", new Environment());
    try {
        // start job
        final ProgramTargetDescriptor targetDescriptor = executor.executeUpdate(session, "INSERT INTO TableSourceSink SELECT IntegerField1 = 42, StringField1 FROM TableNumber1");
        // wait for job completion and verify result
        boolean isRunning = true;
        while (isRunning) {
            // slow the processing down
            Thread.sleep(50);
            final JobStatus jobStatus = clusterClient.getJobStatus(JobID.fromHexString(targetDescriptor.getJobId())).get();
            switch(jobStatus) {
                case CREATED:
                case RUNNING:
                    continue;
                case FINISHED:
                    isRunning = false;
                    verifySinkResult(csvOutputPath);
                    break;
                default:
                    fail("Unexpected job status.");
            }
        }
    } finally {
        executor.stop(session);
    }
}

@Test
public void testSnapshot() throws UnknownHostException {
    final RowTypeInfo type = new RowTypeInfo(Types.STRING, Types.LONG);
    TestMaterializedCollectStreamResult<?> result = null;
    try {
        result = new TestMaterializedCollectStreamResult<>(type, new ExecutionConfig(), InetAddress.getLocalHost(), 0, Integer.MAX_VALUE);
        result.isRetrieving = true;
        result.processRecord(Tuple2.of(true, Row.of("A", 1)));
        result.processRecord(Tuple2.of(true, Row.of("B", 1)));
        result.processRecord(Tuple2.of(true, Row.of("A", 1)));
        result.processRecord(Tuple2.of(true, Row.of("C", 2)));
        assertEquals(TypedResult.payload(4), result.snapshot(1));
        assertEquals(Collections.singletonList(Row.of("A", 1)), result.retrievePage(1));
        assertEquals(Collections.singletonList(Row.of("B", 1)), result.retrievePage(2));
        assertEquals(Collections.singletonList(Row.of("A", 1)), result.retrievePage(3));
        assertEquals(Collections.singletonList(Row.of("C", 2)), result.retrievePage(4));
        result.processRecord(Tuple2.of(false, Row.of("A", 1)));
        assertEquals(TypedResult.payload(3), result.snapshot(1));
        assertEquals(Collections.singletonList(Row.of("A", 1)), result.retrievePage(1));
        assertEquals(Collections.singletonList(Row.of("B", 1)), result.retrievePage(2));
        assertEquals(Collections.singletonList(Row.of("C", 2)), result.retrievePage(3));
        result.processRecord(Tuple2.of(false, Row.of("C", 2)));
        result.processRecord(Tuple2.of(false, Row.of("A", 1)));
        assertEquals(TypedResult.payload(1), result.snapshot(1));
        assertEquals(Collections.singletonList(Row.of("B", 1)), result.retrievePage(1));
    } finally {
        if (result != null) {
            result.close();
        }
    }
}

@Test
public void testLimitedSnapshot() throws UnknownHostException {
    final RowTypeInfo type = new RowTypeInfo(Types.STRING, Types.LONG);
    TestMaterializedCollectStreamResult<?> result = null;
    try {
        result = new TestMaterializedCollectStreamResult<>(type, new ExecutionConfig(), InetAddress.getLocalHost(), 0, // limit the materialized table to 2 rows
        2, // with 3 rows overcommitment
        3);
        result.isRetrieving = true;
        result.processRecord(Tuple2.of(true, Row.of("D", 1)));
        result.processRecord(Tuple2.of(true, Row.of("A", 1)));
        result.processRecord(Tuple2.of(true, Row.of("B", 1)));
        result.processRecord(Tuple2.of(true, Row.of("A", 1)));
        assertEquals(// two over-committed rows
        Arrays.asList(null, null, Row.of("B", 1), Row.of("A", 1)), result.getMaterializedTable());
        assertEquals(TypedResult.payload(2), result.snapshot(1));
        assertEquals(Collections.singletonList(Row.of("B", 1)), result.retrievePage(1));
        assertEquals(Collections.singletonList(Row.of("A", 1)), result.retrievePage(2));
        result.processRecord(Tuple2.of(true, Row.of("C", 1)));
        assertEquals(// limit clean up has taken place
        Arrays.asList(Row.of("A", 1), Row.of("C", 1)), result.getMaterializedTable());
        result.processRecord(Tuple2.of(false, Row.of("A", 1)));
        assertEquals(// regular clean up has taken place
        Collections.singletonList(Row.of("C", 1)), result.getMaterializedTable());
    } finally {
        if (result != null) {
            result.close();
        }
    }
}

