/**
 * FLINK-5985
 *
 * <p>This test ensures we can restore from a savepoint under modifications to the job graph that only concern
 * stateless operators.
 */
@Test
public void testCanRestoreWithModifiedStatelessOperators() throws Exception {
    // Config
    int numTaskManagers = 2;
    int numSlotsPerTaskManager = 2;
    int parallelism = 2;
    // Test deadline
    final Deadline deadline = Deadline.now().plus(Duration.ofMinutes(5));
    // Flink configuration
    final Configuration config = new Configuration();
    config.setString(CheckpointingOptions.SAVEPOINT_DIRECTORY, savepointDir.toURI().toString());
    String savepointPath;
    LOG.info("Flink configuration: " + config + ".");
    // Start Flink
    MiniClusterWithClientResource cluster = new MiniClusterWithClientResource(new MiniClusterResourceConfiguration.Builder().setConfiguration(config).setNumberTaskManagers(numTaskManagers).setNumberSlotsPerTaskManager(numSlotsPerTaskManager).build());
    LOG.info("Shutting down Flink cluster.");
    cluster.before();
    ClusterClient<?> client = cluster.getClusterClient();
    try {
        final StatefulCounter statefulCounter = new StatefulCounter();
        StatefulCounter.resetForTest(parallelism);
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(parallelism);
        env.addSource(new InfiniteTestSource()).shuffle().map(value -> 4 * value).shuffle().map(statefulCounter).uid("statefulCounter").shuffle().map(value -> 2 * value).addSink(new DiscardingSink<>());
        JobGraph originalJobGraph = env.getStreamGraph().getJobGraph();
        client.setDetached(true);
        JobSubmissionResult submissionResult = client.submitJob(originalJobGraph, SavepointITCase.class.getClassLoader());
        JobID jobID = submissionResult.getJobID();
        // wait for the Tasks to be ready
        StatefulCounter.getProgressLatch().await(deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS);
        savepointPath = client.triggerSavepoint(jobID, null).get();
        LOG.info("Retrieved savepoint: " + savepointPath + ".");
    } finally {
        // Shut down the Flink cluster (thereby canceling the job)
        LOG.info("Shutting down Flink cluster.");
        cluster.after();
    }
    // create a new MiniCluster to make sure we start with completely
    // new resources
    cluster = new MiniClusterWithClientResource(new MiniClusterResourceConfiguration.Builder().setConfiguration(config).setNumberTaskManagers(numTaskManagers).setNumberSlotsPerTaskManager(numSlotsPerTaskManager).build());
    LOG.info("Restarting Flink cluster.");
    cluster.before();
    client = cluster.getClusterClient();
    try {
        // Reset static test helpers
        StatefulCounter.resetForTest(parallelism);
        // Gather all task deployment descriptors
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(parallelism);
        // generate a modified job graph that adds a stateless op
        env.addSource(new InfiniteTestSource()).shuffle().map(new StatefulCounter()).uid("statefulCounter").shuffle().map(value -> value).addSink(new DiscardingSink<>());
        JobGraph modifiedJobGraph = env.getStreamGraph().getJobGraph();
        // Set the savepoint path
        modifiedJobGraph.setSavepointRestoreSettings(SavepointRestoreSettings.forPath(savepointPath));
        LOG.info("Resubmitting job " + modifiedJobGraph.getJobID() + " with " + "savepoint path " + savepointPath + " in detached mode.");
        // Submit the job
        client.setDetached(true);
        client.submitJob(modifiedJobGraph, SavepointITCase.class.getClassLoader());
        // Await state is restored
        StatefulCounter.getRestoreLatch().await(deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS);
        // Await some progress after restore
        StatefulCounter.getProgressLatch().await(deadline.timeLeft().toMillis(), TimeUnit.MILLISECONDS);
    } finally {
        cluster.after();
    }
}

@Test
public void testSavepointForJobWithIteration() throws Exception {
    for (int i = 0; i < ITER_TEST_PARALLELISM; ++i) {
        iterTestSnapshotWait[i] = new OneShotLatch();
        iterTestRestoreWait[i] = new OneShotLatch();
        iterTestCheckpointVerify[i] = 0;
    }
    final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
    final IntegerStreamSource source = new IntegerStreamSource();
    IterativeStream<Integer> iteration = env.addSource(source).flatMap(new RichFlatMapFunction<Integer, Integer>() {

        private static final long serialVersionUID = 1L;

        @Override
        public void flatMap(Integer in, Collector<Integer> clctr) throws Exception {
            clctr.collect(in);
        }
    }).setParallelism(ITER_TEST_PARALLELISM).keyBy(new KeySelector<Integer, Object>() {

        private static final long serialVersionUID = 1L;

        @Override
        public Object getKey(Integer value) throws Exception {
            return value;
        }
    }).flatMap(new DuplicateFilter()).setParallelism(ITER_TEST_PARALLELISM).iterate();
    DataStream<Integer> iterationBody = iteration.map(new MapFunction<Integer, Integer>() {

        private static final long serialVersionUID = 1L;

        @Override
        public Integer map(Integer value) throws Exception {
            return value;
        }
    }).setParallelism(ITER_TEST_PARALLELISM);
    iteration.closeWith(iterationBody);
    StreamGraph streamGraph = env.getStreamGraph();
    streamGraph.setJobName("Test");
    JobGraph jobGraph = streamGraph.getJobGraph();
    Configuration config = getFileBasedCheckpointsConfig();
    config.addAll(jobGraph.getJobConfiguration());
    config.setString(TaskManagerOptions.MANAGED_MEMORY_SIZE, "0");
    MiniClusterWithClientResource cluster = new MiniClusterWithClientResource(new MiniClusterResourceConfiguration.Builder().setConfiguration(config).setNumberTaskManagers(1).setNumberSlotsPerTaskManager(2 * jobGraph.getMaximumParallelism()).build());
    cluster.before();
    ClusterClient<?> client = cluster.getClusterClient();
    String savepointPath = null;
    try {
        client.setDetached(true);
        client.submitJob(jobGraph, SavepointITCase.class.getClassLoader());
        for (OneShotLatch latch : iterTestSnapshotWait) {
            latch.await();
        }
        savepointPath = client.triggerSavepoint(jobGraph.getJobID(), null).get();
        client.cancel(jobGraph.getJobID());
        while (!client.getJobStatus(jobGraph.getJobID()).get().isGloballyTerminalState()) {
            Thread.sleep(100);
        }
        jobGraph = streamGraph.getJobGraph();
        jobGraph.setSavepointRestoreSettings(SavepointRestoreSettings.forPath(savepointPath));
        client.setDetached(true);
        client.submitJob(jobGraph, SavepointITCase.class.getClassLoader());
        for (OneShotLatch latch : iterTestRestoreWait) {
            latch.await();
        }
        client.cancel(jobGraph.getJobID());
        while (!client.getJobStatus(jobGraph.getJobID()).get().isGloballyTerminalState()) {
            Thread.sleep(100);
        }
    } finally {
        if (null != savepointPath) {
            client.disposeSavepoint(savepointPath);
        }
        cluster.after();
    }
}

/**
 * Runs the following program.
 * <pre>
 *     [ (source)->(filter) ] -> [ (co-map) ] -> [ (map) ] -> [ (groupBy/reduce)->(sink) ]
 * </pre>
 */
@Test
public void testProgram() {
    try {
        final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        assertEquals("test setup broken", PARALLELISM, env.getParallelism());
        env.enableCheckpointing(500);
        env.setRestartStrategy(RestartStrategies.fixedDelayRestart(Integer.MAX_VALUE, 0L));
        final int numElements = 10000;
        final int numTaskTotal = PARALLELISM * 5;
        DataStream<Long> stream = env.addSource(new GeneratingSourceFunction(numElements, numTaskTotal));
        stream.// -------------- first vertex, chained to the src ----------------
        filter(new LongRichFilterFunction()).// -------------- second vertex, applying the co-map ----------------
        connect(stream).flatMap(new LeftIdentityCoRichFlatMapFunction()).// -------------- third vertex - the stateful one that also fails ----------------
        map(new IdentityMapFunction()).startNewChain().// -------------- fourth vertex - reducer and the sink ----------------
        keyBy(0).reduce(new OnceFailingReducer(numElements)).addSink(new DiscardingSink<Tuple1<Long>>());
        env.execute();
        final long failureCheckpointID = OnceFailingReducer.failureCheckpointID;
        assertNotEquals(0L, failureCheckpointID);
        List<List<Long>[]> allLists = Arrays.asList(GeneratingSourceFunction.COMPLETED_CHECKPOINTS, LongRichFilterFunction.COMPLETED_CHECKPOINTS, LeftIdentityCoRichFlatMapFunction.COMPLETED_CHECKPOINTS, IdentityMapFunction.COMPLETED_CHECKPOINTS, OnceFailingReducer.COMPLETED_CHECKPOINTS);
        for (List<Long>[] parallelNotifications : allLists) {
            for (List<Long> notifications : parallelNotifications) {
                assertTrue("No checkpoint notification was received.", notifications.size() > 0);
                assertFalse("Failure checkpoint was marked as completed.", notifications.contains(failureCheckpointID));
                assertFalse("No checkpoint received after failure.", notifications.get(notifications.size() - 1) == failureCheckpointID);
                assertTrue("Checkpoint notification was received multiple times", notifications.size() == new HashSet<Long>(notifications).size());
            }
        }
    } catch (Exception e) {
        e.printStackTrace();
        fail(e.getMessage());
    }
}

/**
 * Runs the following program the test program defined in {@link #testProgram(StreamExecutionEnvironment)}
 * followed by the checks in {@link #postSubmit}.
 */
@Test
public void runCheckpointedProgram() throws Exception {
    try {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(PARALLELISM);
        env.enableCheckpointing(500);
        env.getConfig().disableSysoutLogging();
        env.setRestartStrategy(RestartStrategies.fixedDelayRestart(Integer.MAX_VALUE, 0L));
        testProgram(env);
        JobGraph jobGraph = env.getStreamGraph().getJobGraph();
        try {
            cluster.getClusterClient().submitJob(jobGraph, getClass().getClassLoader()).getJobExecutionResult();
        } catch (ProgramInvocationException root) {
            Throwable cause = root.getCause();
            // search for nested SuccessExceptions
            int depth = 0;
            while (!(cause instanceof SuccessException)) {
                if (cause == null || depth++ == 20) {
                    root.printStackTrace();
                    fail("Test failed: " + root.getMessage());
                } else {
                    cause = cause.getCause();
                }
            }
        }
        postSubmit();
    } catch (Exception e) {
        e.printStackTrace();
        Assert.fail(e.getMessage());
    }
}

